import pandas as pd
from datetime import datetime
import requests
import json

def check_balance(term):
    url = "https://api.eppc.com/check_balance"
    headers = {"Authorization": "Bearer " + term}
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return pd.read_json(response.content)
    else:
        return pd.DataFrame()

def calculate_difference():
    balance_2_to_5_years = check_balance("2 to 5 years")
